import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Link } from 'react-router-dom';
import SliderHeader from '../../ui/Slider/SliderHeader';
import SliderControls from '../../ui/Slider/SliderControls';
import { articlesData as rawArticles } from "../../../data/pages/articles";
import { useArticles } from '../../../context/ArticlesContext';
import './ArticleSection.css';

const ArticleSection = () => {
  const { slugMap, loading } = useArticles();
  const articlesData = React.useMemo(() => {
    return Object.values(slugMap).sort((a, b) => {
      // Prioritize rawDate (Post Date) for editorial order
      const timeA = a.rawDate ? new Date(a.rawDate).getTime() : (a.createdAt?.seconds ? a.createdAt.seconds * 1000 : 0);
      const timeB = b.rawDate ? new Date(b.rawDate).getTime() : (b.createdAt?.seconds ? b.createdAt.seconds * 1000 : 0);

      return timeB - timeA; // Descending order (newest first)
    });
  }, [slugMap]);

  // We clone items for seamless loop: items at end added to start, items at start added to end
  const [currentIndex, setCurrentIndex] = useState(4);
  const [isTransitioning, setIsTransitioning] = useState(false);
  const [visibleItems, setVisibleItems] = useState(4);
  const sliderRef = useRef(null);
  const touchStartRef = useRef(0);
  const isMovingRef = useRef(false);

  // Extend data for seamless cloning
  const clonedData = React.useMemo(() => {
    if (articlesData.length === 0) return [];
    return [
      ...articlesData.slice(-4),
      ...articlesData,
      ...articlesData.slice(0, 4)
    ];
  }, [articlesData]);

  const totalRealItems = articlesData.length;

  useEffect(() => {
    if (totalRealItems > 0 && currentIndex === 0) {
      setCurrentIndex(4);
    }
  }, [totalRealItems, currentIndex]);

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 640) setVisibleItems(1);
      else if (window.innerWidth < 768) setVisibleItems(2);
      else if (window.innerWidth < 1024) setVisibleItems(3);
      else if (window.innerWidth < 1440) setVisibleItems(4);
      else setVisibleItems(5);
    };

    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const moveToIndex = useCallback((index, smooth = true) => {
    setIsTransitioning(smooth);
    setCurrentIndex(index);
  }, []);

  const nextSlide = useCallback(() => {
    if (isMovingRef.current) return;
    moveToIndex(currentIndex + 1);
  }, [currentIndex, moveToIndex]);

  const prevSlide = useCallback(() => {
    if (isMovingRef.current) return;
    moveToIndex(currentIndex - 1);
  }, [currentIndex, moveToIndex]);

  // Boundary check for infinite loop
  useEffect(() => {
    // Jump from end clone back to real start
    if (currentIndex >= totalRealItems + 4) {
      const timer = setTimeout(() => {
        moveToIndex(4, false);
      }, 600);
      return () => clearTimeout(timer);
    }
    // Jump from start clone forward to real end
    if (currentIndex <= 3) {
      const timer = setTimeout(() => {
        moveToIndex(totalRealItems + 3, false);
      }, 600);
      return () => clearTimeout(timer);
    }
  }, [currentIndex, totalRealItems, moveToIndex]);

  // Touch Handling
  const handleTouchStart = (e) => {
    touchStartRef.current = e.touches[0].clientX;
  };

  const handleTouchEnd = (e) => {
    const touchEnd = e.changedTouches[0].clientX;
    const diff = touchStartRef.current - touchEnd;
    if (Math.abs(diff) > 50) {
      if (diff > 0) nextSlide();
      else prevSlide();
    }
  };

  const getTranslateX = () => {
    const percentage = (100 / visibleItems) * currentIndex;
    return `translateX(-${percentage}%)`;
  };

  const [openCardId, setOpenCardId] = useState(null);

  const handleCardClick = (id) => {
    setOpenCardId(prev => prev === id ? null : id);
  };

  // Early returns must happen AFTER all hooks are called!
  if (loading) {
    return (
      <div className="py-20 flex items-center justify-center">
        <div className="text-brand-red text-xl font-bold animate-pulse uppercase tracking-[0.3em]">
          Reading Scrolls...
        </div>
      </div>
    );
  }

  if (totalRealItems === 0) return null;

  return (
    <section className="article-section">
      <div className="section-container">
        <SliderHeader
          title="Featured Articles"
          subTitle="Explore our latest insights and sacred wisdom."
          onNext={nextSlide}
          onPrev={prevSlide}
          isPrevDisabled={false}
          isNextDisabled={false}
        />

        <div
          className="article-slider-container"
          onTouchStart={handleTouchStart}
          onTouchEnd={handleTouchEnd}
        >
          <div
            className="article-track"
            style={{
              transform: getTranslateX(),
              transition: isTransitioning ? 'transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94)' : 'none'
            }}
          >
            {clonedData.map((article, index) => {
              const uniqueId = `${article.id}-${index}`;
              const isOpen = openCardId === uniqueId;

              return (
                <div
                  key={uniqueId}
                  className="article-slide"
                  style={{ flex: `0 0 ${100 / visibleItems}%` }}
                >
                  <div className="article-item">
                    <div
                      className={`article-wrapper ${isOpen ? 'is-open' : ''}`}
                      onClick={() => handleCardClick(uniqueId)}
                    >
                      {/* Inner page content ΓÇö revealed when cover opens */}
                      <div className="article-inner">
                        <h4 className="article-inner-title">{article.title}</h4>
                        {article.hindi && <h5 className="article-inner-hindi-title">{article.hindi}</h5>}
                        <div className="article-inner-meta">
                          {article.author && <span className="article-inner-author">By {article.author}</span>}
                          {(article.data || article.createdAt) && (
                            <span className="article-inner-date">
                              {article.data || (article.createdAt?.seconds ? new Date(article.createdAt.seconds * 1000).toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" }) : "")}
                            </span>
                          )}
                        </div>
                        <Link to={`/articles/${article.id}`} className="article-read-more" onClick={(e) => e.stopPropagation()}>Read More</Link>
                      </div>
                      {/* Cover ΓÇö rotates open on hover/click */}
                      <div className="article-cover-container">
                        <div className="w-full aspect-video overflow-hidden">
                          <img
                            src={article.imageUrl || article.img}
                            alt={article.title}
                            className="w-full h-full object-contain"
                            loading="eager"
                          />
                        </div>
                        <div className="article-cover-content">
                          <h4 className="article-cover-title">{article.title}</h4>
                          {article.author && <p className="article-cover-author">By {article.author}</p>}
                          {(article.data || article.createdAt) && (
                            <p className="article-cover-date">
                              {article.data || (article.createdAt?.seconds ? new Date(article.createdAt.seconds * 1000).toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" }) : "")}
                            </p>
                          )}
                        </div>
                      </div>
                    </div>

                  </div>
                </div>
              );
            })}
          </div>
        </div>

        <SliderControls
          onNext={nextSlide}
          onPrev={prevSlide}
          isPrevDisabled={false}
          isNextDisabled={false}
        />
      </div>
    </section>
  );
};

export default ArticleSection;

import React, { useState, useRef } from "react";
import { IoLocationOutline, IoCallOutline, IoTimeOutline } from "react-icons/io5";
import { collection, addDoc, serverTimestamp } from "firebase/firestore";
import { db } from "../../../firebaseConfig";
import ReCAPTCHA from "react-google-recaptcha";
import { homeData } from "../../../data/pages/home";
import { footerData } from "../../../data/layout/footer";
import "./Contact.css";

const { contact: contactContent } = homeData;
const { contact: contactInfo } = footerData;

const Contact = () => {
  const [formData, setFormData] = useState({ name: "", email: "", phone: "", message: "" });
  const [status, setStatus] = useState("idle"); // idle | loading | success | error
  const [captchaToken, setCaptchaToken] = useState(null);
  const recaptchaRef = useRef(null);

  const recaptchaSiteKey = import.meta.env.VITE_RECAPTCHA_SITE_KEY || "6LeIxAcTAAAAAJcZVRqyHh71UMIEGNQ_MXjiZKhI"; // Fallback to testing key if not set

  const handleChange = (e) => {
    setFormData((prev) => ({ ...prev, [e.target.name]: e.target.value }));
  };

  const onCaptchaChange = (token) => {
    setCaptchaToken(token);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!formData.name || !formData.email || !formData.message) return;
    if (!captchaToken) {
      alert("Please verify that you are not a robot.");
      return;
    }

    setStatus("loading");
    try {
      await addDoc(collection(db, "Astro_Contact"), {
        ...formData,
        captchaVerified: true,
        createdAt: serverTimestamp(),
      });
      setStatus("success");
      setFormData({ name: "", email: "", phone: "", message: "" });
      setCaptchaToken(null);
      if (recaptchaRef.current) recaptchaRef.current.reset();
    } catch (err) {
      console.error("Contact form error:", err);
      setStatus("error");
    }
  };

  return (
    <section className="contact-section" id="contact">
      <div className="section-container">
        <div className="contact-header">
          <p className="contact-label">{contactContent.label}</p>
          <h2 className="title-batangas text-4xl md:text-5xl font-bold uppercase tracking-tight leading-tight">
            {contactContent.title}
          </h2>
          <p className="subtitle-poppins text-lg md:text-xl font-medium">
            {contactContent.subtitle}
          </p>
        </div>

        <div className="contact-grid">
          <div className="contact-info">
            <p className="contact-desc subtitle-poppins">
              {contactContent.description}
            </p>

            <ul className="contact-list">
              <li>
                <div className="contact-icon">
                  <IoLocationOutline size={24} />
                </div>
                <div className="contact-text-group">
                  <h3 className="title-batangas">Our Address</h3>
                  <a
                    href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(contactInfo.address)}`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="contact-link"
                  >
                    <p className="subtitle-poppins">{contactInfo.address}</p>
                  </a>
                </div>
              </li>

              <li>
                <div className="contact-icon">
                  <IoCallOutline size={24} />
                </div>
                <div className="contact-text-group">
                  <h3 className="title-batangas">Contact</h3>
                  <a href={`tel:${contactInfo.phone.replace(/\s/g, '')}`} className="contact-link">
                    <p className="subtitle-poppins">LandLine: {contactInfo.phone}</p>
                  </a>
                  <a href={`mailto:${contactInfo.email}`} className="contact-link">
                    <p className="subtitle-poppins">Email: {contactInfo.email}</p>
                  </a>
                </div>
              </li>

              <li>
                <div className="contact-icon">
                  <IoTimeOutline size={24} />
                </div>
                <div className="contact-text-group">
                  <h3 className="title-batangas">Working Hours</h3>
                  <p className="subtitle-poppins">{contactContent.workingHours.weekdays}</p>
                  <p className="subtitle-poppins">{contactContent.workingHours.sunday}</p>
                </div>
              </li>
            </ul>
          </div>

          <div className="contact-card">
            <h2 className="title-batangas">{contactContent.formTitle}</h2>

            <form className="contact-form" onSubmit={handleSubmit}>
              <div className="input-group">
                <input
                  type="text"
                  name="name"
                  value={formData.name}
                  onChange={handleChange}
                  placeholder="Your name"
                  required
                />
              </div>
              <div className="input-group">
                <input
                  type="email"
                  name="email"
                  value={formData.email}
                  onChange={handleChange}
                  placeholder="Your email address"
                  required
                />
              </div>
              <div className="input-group">
                <input
                  type="tel"
                  name="phone"
                  value={formData.phone}
                  onChange={handleChange}
                  placeholder="Your phone number"
                />
              </div>
              <div className="input-group">
                <textarea
                  name="message"
                  value={formData.message}
                  onChange={handleChange}
                  rows="4"
                  placeholder="Write your message..."
                  required
                />
              </div>
              {status === "success" && (
                <p className="text-green-400 text-sm text-center subtitle-poppins mb-2">
                  Γ£à Message sent! We'll get back to you shortly.
                </p>
              )}
              {status === "error" && (
                <p className="text-red-400 text-sm text-center subtitle-poppins mb-2">
                  Γ¥î Something went wrong. Please try again.
                </p>
              )}

              <button
                type="submit"
                className="contact-submit-btn"
                disabled={status === "loading" || !captchaToken}
              >
                {status === "loading" ? "Sending..." : "Send Message"}
              </button>
            </form>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Contact;

import React, { useEffect, useMemo, useRef, useState } from "react";
import {
  motion,
  useTransform,
  useScroll,
  useMotionValueEvent,
} from "framer-motion";
import { useNavigate } from "react-router-dom";
import { useCourses } from "../../../context/CoursesContext";
import "./CourseSection.css";

const useViewportWidth = () => {
  const [width, setWidth] = useState(
    typeof window !== "undefined" ? window.innerWidth : 1200
  );

  useEffect(() => {
    const handleResize = () => {
      setWidth(window.innerWidth);
    };

    handleResize();
    window.addEventListener("resize", handleResize);

    return () => window.removeEventListener("resize", handleResize);
  }, []);

  return width;
};

const CourseSection = () => {
  const { slugMap, loading } = useCourses();
  const coursesData = useMemo(() => Object.values(slugMap), [slugMap]);

  if (loading) {
    return (
      <div className="py-20 flex items-center justify-center course-section-container">
        <div className="course-section-loading">Unveiling Wisdom...</div>
      </div>
    );
  }

  if (coursesData.length === 0) {
    return null;
  }

  return (
    <section className="course-section">
      <div className="course-section-header">

        <h2 className="title-batangas course-section-title">
          Courses for Astrologer
        </h2>

        <p className="subtitle-poppins course-section-subtitle">
          It&apos;s not just a course ΓÇö it&apos;s a life-changing journey into
          celestial wisdom.
        </p>
      </div>

      <HorizontalScrollCarousel items={coursesData} />
    </section>
  );
};

const HorizontalScrollCarousel = ({ items }) => {
  const targetRef = useRef(null);
  const stickyRef = useRef(null);
  const viewportWidth = useViewportWidth();

  const [activeIndex, setActiveIndex] = useState(0);
  const [hoveredIndex, setHoveredIndex] = useState(null);
  const [isDraggingState, setIsDraggingState] = useState(false);

  const { scrollYProgress } = useScroll({
    target: targetRef,
    offset: ["start start", "end end"],
  });

  const isMobile = viewportWidth < 640;
  const cardWidth = isMobile ? 300 : 340;
  const gap = isMobile ? 24 : 52;

  const totalWidth = items.length * cardWidth + (items.length - 1) * gap;

  const startX = viewportWidth / 2 - cardWidth / 2;
  const endX = viewportWidth / 2 - (totalWidth - cardWidth / 2);

  const x = useTransform(scrollYProgress, [0, 1], [startX, endX]);

  useMotionValueEvent(scrollYProgress, "change", (latest) => {
    if (!items.length) return;

    const nextIndex = Math.round(latest * (items.length - 1));
    const safeIndex = Math.min(Math.max(nextIndex, 0), items.length - 1);

    setActiveIndex(safeIndex);
  });

  // Drag-to-scroll state refs
  const isDragging = useRef(false);
  const startXRef = useRef(0);
  const startYRef = useRef(0);
  const startScrollY = useRef(0);
  const currentDeltaX = useRef(0);
  const isFirstMove = useRef(true);
  const isSwipeHorizontal = useRef(null);
  const preventClickRef = useRef(false);

  const handleMouseDown = (e) => {
    // Only drag with left click
    if (e.button !== 0) return;

    isDragging.current = true;
    setIsDraggingState(true);
    startXRef.current = e.clientX;
    startScrollY.current = window.scrollY;
    currentDeltaX.current = 0;
    preventClickRef.current = false;

    window.addEventListener("mousemove", onWindowMouseMove.current);
    window.addEventListener("mouseup", onWindowMouseUp.current);
  };

  const handleMouseMove = (e) => {
    if (!isDragging.current) return;

    const deltaX = e.clientX - startXRef.current;
    currentDeltaX.current = deltaX;

    if (Math.abs(deltaX) > 5) {
      preventClickRef.current = true;
    }

    if (!targetRef.current) return;

    const rect = targetRef.current.getBoundingClientRect();
    const startScrollLimit = rect.top + window.scrollY;
    const scrollableDistance = targetRef.current.offsetHeight - window.innerHeight;
    const endScrollLimit = startScrollLimit + scrollableDistance;

    const translationDistance = Math.abs(startX - endX);
    if (translationDistance === 0) return;

    const ratio = scrollableDistance / translationDistance;
    const targetScrollY = Math.max(
      startScrollLimit,
      Math.min(endScrollLimit, startScrollY.current - deltaX * ratio)
    );

    window.scrollTo(0, targetScrollY);
  };

  const handleMouseUp = () => {
    isDragging.current = false;
    setIsDraggingState(false);

    window.removeEventListener("mousemove", onWindowMouseMove.current);
    window.removeEventListener("mouseup", onWindowMouseUp.current);

    if (preventClickRef.current) {
      setTimeout(() => {
        preventClickRef.current = false;
      }, 50);
    }
  };

  const handleTouchStart = (e) => {
    const touch = e.touches[0];
    isDragging.current = true;
    setIsDraggingState(true);
    startXRef.current = touch.clientX;
    startYRef.current = touch.clientY;
    startScrollY.current = window.scrollY;
    currentDeltaX.current = 0;
    isFirstMove.current = true;
    isSwipeHorizontal.current = null;
    preventClickRef.current = false;
  };

  const handleTouchMove = (e) => {
    if (!isDragging.current) return;
    const touch = e.touches[0];

    const deltaX = touch.clientX - startXRef.current;
    const deltaY = touch.clientY - startYRef.current;
    currentDeltaX.current = deltaX;

    if (isFirstMove.current) {
      if (Math.abs(deltaX) > Math.abs(deltaY)) {
        isSwipeHorizontal.current = true;
        preventClickRef.current = true;
      } else {
        isSwipeHorizontal.current = false;
        isDragging.current = false;
        setIsDraggingState(false);
      }
      isFirstMove.current = false;
    }

    if (isSwipeHorizontal.current) {
      if (e.cancelable) {
        e.preventDefault();
      }

      if (!targetRef.current) return;

      const rect = targetRef.current.getBoundingClientRect();
      const startScrollLimit = rect.top + window.scrollY;
      const scrollableDistance = targetRef.current.offsetHeight - window.innerHeight;
      const endScrollLimit = startScrollLimit + scrollableDistance;

      const translationDistance = Math.abs(startX - endX);
      if (translationDistance === 0) return;

      const ratio = scrollableDistance / translationDistance;
      const targetScrollY = Math.max(
        startScrollLimit,
        Math.min(endScrollLimit, startScrollY.current - deltaX * ratio)
      );

      window.scrollTo(0, targetScrollY);
    }
  };

  const handleTouchEnd = () => {
    isDragging.current = false;
    setIsDraggingState(false);

    if (preventClickRef.current) {
      setTimeout(() => {
        preventClickRef.current = false;
      }, 50);
    }
  };

  // Stable listener wrapper ref
  const dragHandlersRef = useRef({});
  dragHandlersRef.current = {
    handleMouseMove,
    handleMouseUp,
    handleTouchStart,
    handleTouchMove,
    handleTouchEnd,
  };

  const onWindowMouseMove = useRef((e) => {
    dragHandlersRef.current.handleMouseMove?.(e);
  });
  const onWindowMouseUp = useRef((e) => {
    dragHandlersRef.current.handleMouseUp?.(e);
  });

  useEffect(() => {
    const stickyEl = stickyRef.current;
    if (!stickyEl) return;

    const onTouchStart = (e) => dragHandlersRef.current.handleTouchStart?.(e);
    const onTouchMove = (e) => dragHandlersRef.current.handleTouchMove?.(e);
    const onTouchEnd = (e) => dragHandlersRef.current.handleTouchEnd?.(e);

    stickyEl.addEventListener("touchstart", onTouchStart, { passive: true });
    stickyEl.addEventListener("touchmove", onTouchMove, { passive: false });
    stickyEl.addEventListener("touchend", onTouchEnd, { passive: true });

    return () => {
      stickyEl.removeEventListener("touchstart", onTouchStart);
      stickyEl.removeEventListener("touchmove", onTouchMove);
      stickyEl.removeEventListener("touchend", onTouchEnd);

      window.removeEventListener("mousemove", onWindowMouseMove.current);
      window.removeEventListener("mouseup", onWindowMouseUp.current);
    };
  }, []);

  const handleClickCapture = (e) => {
    if (preventClickRef.current) {
      e.stopPropagation();
      e.preventDefault();
    }
  };

  return (
    <section
      ref={targetRef}
      className="relative h-[300vh] course-carousel-section"
    >
      <div
        ref={stickyRef}
        onMouseDown={handleMouseDown}
        onClickCapture={handleClickCapture}
        className={`sticky top-0 flex h-screen items-center overflow-hidden course-carousel-sticky ${
          isDraggingState ? "is-dragging" : ""
        }`}
        style={{ perspective: "1200px" }}
      >
        <motion.div
          style={{
            x,
            gap,
            transformStyle: "preserve-3d",
          }}
          className="flex px-4 course-carousel-track"
        >
          {items.map((course, index) => (
            <Card
              key={course.id || course.slug || index}
              course={course}
              index={index}
              activeIndex={activeIndex}
              hoveredIndex={hoveredIndex}
              setHoveredIndex={setHoveredIndex}
              scrollYProgress={scrollYProgress}
              itemsCount={items.length}
            />
          ))}
        </motion.div>
      </div>
    </section>
  );
};

const Card = ({
  course,
  index,
  activeIndex,
  hoveredIndex,
  setHoveredIndex,
  scrollYProgress,
  itemsCount,
}) => {
  const navigate = useNavigate();

  const bgImage = course.imageUrl || course.bgImage || "/placeholder-image.jpg";
  const courseType = course.type === "free" ? "free" : "paid";
  const courseUrl = `/courses/${courseType}/${course.slug}`;

  const isActive = activeIndex === index;
  const isHovered = hoveredIndex === index;
  const cardNum = String(index + 1).padStart(2, "0");

  const N = itemsCount;
  const centerProgress = N > 1 ? index / (N - 1) : 0.5;
  const step = N > 1 ? 0.7 / (N - 1) : 0.4;

  const rotateY = useTransform(
    scrollYProgress,
    [centerProgress - step, centerProgress, centerProgress + step],
    [-32, 0, 32]
  );

  const scale = useTransform(
    scrollYProgress,
    [centerProgress - step, centerProgress, centerProgress + step],
    [0.82, 1, 0.82]
  );

  const z = useTransform(
    scrollYProgress,
    [centerProgress - step, centerProgress, centerProgress + step],
    [-150, 0, -150]
  );

  const [isBtnHovered, setIsBtnHovered] = useState(false);

  const handleExplore = (e) => {
    e.preventDefault();
    e.stopPropagation();
    navigate(courseUrl);
  };

  return (
    <motion.article
      style={{
        rotateY,
        scale,
        z,
        zIndex: isHovered ? 100 : isActive ? 60 : 10,
        pointerEvents: "none",
        transformStyle: "preserve-3d",
      }}
      className={`course-card-shell ${isActive ? "is-active" : ""} ${isHovered ? "is-hovered" : ""
        }`}
    >
      <div className="course-card-frame" aria-hidden="true">
        <span className="course-card-corner course-card-corner--tl" />
        <span className="course-card-corner course-card-corner--tr" />
        <span className="course-card-corner course-card-corner--bl" />
        <span className="course-card-corner course-card-corner--br" />
      </div>

      <div className="course-card-visual">
        <img
          src={bgImage}
          alt={course.title}
          className="course-card-image"
          draggable={false}
        />
        <div className="course-card-image-vignette" />
        <span className="course-card-number">{cardNum}</span>
        <span className={`course-card-badge ${courseType}`}>
          {courseType === "free" ? "Complimentary" : "Premium"}
        </span>
      </div>

      <div
        className="course-card-content"
        style={{ pointerEvents: isActive || isHovered ? "auto" : "none" }}
        onMouseEnter={() => setHoveredIndex(index)}
        onMouseLeave={() => {
          setHoveredIndex(null);
          setIsBtnHovered(false);
        }}
      >
        <div className="course-card-eyebrow">
          <span className="course-card-eyebrow-line" />
          <span className="course-card-eyebrow-text">Vedic Wisdom</span>
          <span className="course-card-eyebrow-line" />
        </div>

        <h3 className="course-card-title">{course.title}</h3>

        <div className="course-card-divider" aria-hidden="true">
          <span className="course-card-divider-gem">Γùå</span>
        </div>

        <button
          type="button"
          className={`course-card-btn${isBtnHovered ? " is-btn-hovered" : ""}`}
          onMouseEnter={() => setIsBtnHovered(true)}
          onMouseLeave={() => setIsBtnHovered(false)}
          onClick={handleExplore}
        >
          <span className="course-card-btn-text">Explore Course</span>
          <span className="course-card-arrow" aria-hidden="true">
            ΓåÆ
          </span>
        </button>
      </div>
    </motion.article>
  );
};

export default CourseSection;

