    </div>
  );
};

const Products = () => {
  const { products, loading } = useProducts();
  const displayProducts = products.length > 0 ? products : fallbackProducts;

  const [currentIndex, setCurrentIndex] = useState(3);
  const [isTransitioning, setIsTransitioning] = useState(false);
  const [visibleItems, setVisibleItems] = useState(3);
  const autoPlayRef = useRef(null);
  const touchStartRef = useRef(0);

  const clonedData = useMemo(() => {
    if (displayProducts.length === 0) return [];
    return [
      ...displayProducts.slice(-3),
      ...displayProducts,
      ...displayProducts.slice(0, 3)
    ];
  }, [displayProducts]);

  const totalRealItems = displayProducts.length;

  useEffect(() => {
    setCurrentIndex(3);
  }, [totalRealItems]);

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 640) setVisibleItems(1);
      else if (window.innerWidth < 1024) setVisibleItems(2);
      else setVisibleItems(3);
    };
    handleResize();
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  const moveToIndex = useCallback((index, smooth = true) => {
    setIsTransitioning(smooth);
    setCurrentIndex(index);
  }, []);

  const nextSlide = useCallback(() => {
    moveToIndex(currentIndex + 1);
  }, [currentIndex, moveToIndex]);

  const prevSlide = useCallback(() => {
    moveToIndex(currentIndex - 1);
  }, [currentIndex, moveToIndex]);

  const getTranslateX = () => {
    const percentage = (100 / visibleItems) * currentIndex;
    return `translateX(-${percentage}%)`;
  };

  useEffect(() => {
    if (!isTransitioning) return;
    if (currentIndex >= totalRealItems + 3) {
      const timer = setTimeout(() => {
        setIsTransitioning(false);
        setCurrentIndex(3);
      }, 700);
      return () => clearTimeout(timer);
    }
    if (currentIndex <= 2) {
      const timer = setTimeout(() => {
        setIsTransitioning(false);
        setCurrentIndex(totalRealItems + 2);
      }, 700);
      return () => clearTimeout(timer);
    }
  }, [currentIndex, isTransitioning, totalRealItems]);

  const startAutoPlay = useCallback(() => {
    stopAutoPlay();
    autoPlayRef.current = setInterval(nextSlide, 3800);
  }, [nextSlide]);

  const stopAutoPlay = useCallback(() => {
    if (autoPlayRef.current) clearInterval(autoPlayRef.current);
  }, []);

  useEffect(() => {
    if (totalRealItems > 0) {
      startAutoPlay();
    }
    return () => stopAutoPlay();
  }, [startAutoPlay, stopAutoPlay, totalRealItems]);

  const handleTouchStart = (e) => {
    touchStartRef.current = e.touches[0].clientX;
    stopAutoPlay();
  };

  const handleTouchEnd = (e) => {
    const touchEnd = e.changedTouches[0].clientX;
    const diff = touchStartRef.current - touchEnd;
    if (Math.abs(diff) > 50) {
      if (diff > 0) nextSlide();
      else prevSlide();
    }
    startAutoPlay();
  };

  if (loading) {
    return (
      <section className="products-section">
        <div className="section-container">
          <div className="py-20 flex items-center justify-center">
            <div className="text-brand-red text-xl font-bold animate-pulse uppercase tracking-[0.3em]">
              Loading Products...
            </div>
          </div>
        </div>
      </section>
    );
  }

  if (totalRealItems === 0) return null;

  return (
    <section
      className="products-section"
      onMouseEnter={stopAutoPlay}
      onMouseLeave={startAutoPlay}
    >
      <div className="section-container">
        <SliderHeader
          title="Our Sacred Products"
          subTitle="Handpicked spiritual products to elevate your energy and transform your life."
        />

        <div
          className="product-slider-container"
          onTouchStart={handleTouchStart}
          onTouchEnd={handleTouchEnd}
        >
          <div
            className="product-track"
            style={{
              transform: getTranslateX(),
              transition: isTransitioning
                ? 'transform 0.7s cubic-bezier(0.4, 0, 0.2, 1)'
                : 'none'
            }}
          >
            {clonedData.map((p, index) => (
              <div
                className="product-slide"
                key={`${p.id || p.title}-${index}`}
                style={{ flex: `0 0 ${100 / visibleItems}%` }}
              >
                <ProductCard p={p} />
              </div>
            ))}
          </div>
        </div>

        <SliderControls
          onNext={nextSlide}
          onPrev={prevSlide}
          isPrevDisabled={false}
          isNextDisabled={false}
        />

        <div className="flex justify-center mt-10">
          <Link
            to="/products"
            className="inline-flex items-center gap-2 bg-linear-to-br from-[#ff3131] to-[#c30000] text-white px-4 py-4 rounded-full font-black uppercase tracking-[0.12em] transition-all duration-300 hover:shadow-[0_14px_30px_rgba(221,39,39,0.45)] hover:from-[#ff4f4f] hover:to-brand-red shadow-[0_10px_25px_rgba(221,39,39,0.25)] text-sm hover:-translate-y-1"
          >
            View All Products
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d="M5 12h14M12 5l7 7-7 7" /></svg>
          </Link>
        </div>
      </div>
    </section>
  );
};

export default Products;

