import React, { createContext, useContext, useEffect, useState } from "react";
import { collection, getDocs } from "firebase/firestore";
import { db } from "../firebaseConfig";

// Util to convert title to URL slug
const slugify = (text) =>
  text?.toLowerCase().replace(/[^\w ]+/g, "").replace(/ +/g, "-");

const ArticlesContext = createContext();

export const ArticlesProvider = ({ children }) => {
  const [slugMap, setSlugMap] = useState({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchArticles = async () => {
      try {
        const snapshot = await getDocs(collection(db, "Articles"));
        const map = {};
        snapshot.forEach((doc) => {
          const data = doc.data();
          const slug = slugify(data.title);
          map[slug] = { id: doc.id, slug, ...data };
        });

        setSlugMap(map);
      } catch (error) {
        console.error("Error loading articles:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchArticles();
  }, []);

  return (
    <ArticlesContext.Provider value={{ slugMap, loading }}>
      {children}
    </ArticlesContext.Provider>
  );
};

export const useArticles = () => useContext(ArticlesContext);

import React, { createContext, useContext, useEffect, useState } from "react";
import { collection, getDocs } from "firebase/firestore";
import { db } from "../firebaseConfig";

// Create context
const CoursesContext = createContext();

const slugify = (text) =>
  text?.toLowerCase().replace(/[^\w ]+/g, "").replace(/ +/g, "-");

export const CoursesProvider = ({ children }) => {
  const [slugMap, setSlugMap] = useState({});
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchCourses = async () => {
      setLoading(true);
      const map = {};

      // Fetch from both freeCourses and paidCourses
      const courseTypes = ["freeCourses", "paidCourses"];

      for (const type of courseTypes) {
        const snapshot = await getDocs(collection(db, type));
        snapshot.forEach((doc) => {
          const data = doc.data();
          const slug = slugify(data.title);
          map[`${type === "freeCourses" ? "free" : "paid"}/${slug}`] = {
            id: doc.id,
            type: type === "freeCourses" ? "free" : "paid",
            slug,
            ...data,
          };
        });
      }

      setSlugMap(map);
      setLoading(false);
    };

    fetchCourses();
  }, []);

  return (
    <CoursesContext.Provider value={{ slugMap, loading }}>
      {children}
    </CoursesContext.Provider>
  );
};

export const useCourses = () => useContext(CoursesContext);

