import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import { collection, getDocs, query } from "firebase/firestore";
import { db } from "../../firebaseConfig";
import { Helmet } from "react-helmet-async";

const slugify = (text) =>
  text?.toLowerCase().replace(/[^╪Ç-█┐\w ]+/g, "").replace(/ +/g, "-");

const ArticlesPage = () => {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);

  const fetchData = async () => {
    try {
      const articlesQuery = query(
        collection(db, "Articles")
      );
      const querySnapshot = await getDocs(articlesQuery);

      const fetchedData = querySnapshot.docs.map((doc) => ({
        id: doc.id,
        slug: slugify(doc.data().title),
        ...doc.data(),
      }));

      // Sort client-side: support createdAt (Firestore Timestamp), timestamp, or data (string date)
      fetchedData.sort((a, b) => {
        const getTime = (item) => {
          if (item.createdAt?.seconds) return item.createdAt.seconds * 1000;
          if (item.timestamp?.seconds) return item.timestamp.seconds * 1000;
          if (item.data) return new Date(item.data).getTime();
          return 0;
        };
        return getTime(b) - getTime(a);
      });

      setData(fetchedData);
    } catch (error) {
      console.error("Error fetching data:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);
  const getMetaTags = () => {

    return (
      <Helmet>
        <title>Astrology Articles by Valay Patel</title>
        <meta name="description" content={''} />
        <meta
          name="keywords"
          content={''}
        />
      </Helmet>

    );
  };

  return (
    <div
      className="bg-gray-50 min-h-screen text-sm"
      style={{ backgroundImage: "url('https://res.cloudinary.com/dzdnwpocf/image/upload/v1753466267/articalsbg_zjtb2m.jpg')" }}
    >
      {getMetaTags()}
      <div className="bg-cover bg-center h-48 flex items-center justify-center shadow-md">
        <h1 className="text-xl md:text-4xl font-bold text-black">
          Articles & Publications
        </h1>
      </div>

      <div className="container mx-auto py-8 px-4 md:px-8 lg:flex lg:space-x-6">
        <div className="lg:w-3/4">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {data.map((article, index) => (
              <Link to={`/article/${article.slug}`} key={index}>
                <div className="md:w-64 w-72 md:left-0 left-7 bg-white shadow-md rounded-lg overflow-hidden relative">
                  <div className="relative">
                    {article.imageUrl && (
                      <img
                        src={article.imageUrl}
                        alt="Article"
                        className="w-full h-40 object-cover"
                      />
                    )}
                    <div className="absolute -bottom-6 left-2 w-12 h-12 bg-white rounded-full shadow-md flex items-center justify-center">
                      <img
                        src="/src/assets/images/common/logos/vahlay_astro.png"
                        alt="logo"
                        className="w-10 h-10 object-contain rounded-full"
                      />
                    </div>
                  </div>

                  <div className="p-4 flex flex-col h-full">
                    <h3 className="text-sm font-semibold text-gray-800 line-clamp-2 my-3">
                      {article.title?.substring(0, 40)}...
                    </h3>
                    <p className="text-xs text-gray-600 line-clamp-3">
                      {article.hindi?.substring(0, 80)}...
                    </p>
                    <div className="mt-auto pt-4">
                      <Link
                        to={`/article/${article.slug}`}
                        className="text-red-600 text-sm font-semibold hover:underline"
                      >
                        Read More &gt;
                      </Link>
                      <div className="mt-2 text-gray-500 text-xs">
                        {article.author && <span>by {article.author} | </span>}
                        {article.data}
                      </div>
                    </div>
                  </div>
                </div>
              </Link>
            ))}
          </div>
        </div>

        <div className="lg:w-1/4 mt-8 lg:mt-0">
          <div className="bg-white shadow-md rounded-lg p-6">
            <Link to="/courses">
              <button className="w-full bg-red-500 text-white py-2 rounded-lg mb-4">
                Courses
              </button>
            </Link>
            <button className="w-full bg-red-500 text-white py-2 rounded-lg">
              Books
            </button>
          </div>
          <div className="bg-white shadow-md rounded-lg p-6 mt-6">
            <h3 className="text-lg font-semibold mb-4">Articles</h3>
            <ul className=" list-disc space-y-2 text-sm mx-2">
              {data.map((article, index) => (
                <li key={index}>
                  <Link
                    to={`/article/${article.slug}`}
                    className="text-red-600 mb-5"
                  >
                    {article.title}
                  </Link>
                </li>
              ))}
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ArticlesPage;

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { getFirestore, doc, collection, getDocs, updateDoc, setDoc } from "firebase/firestore";
import { app } from "../../firebaseConfig"; // Firebase configuration file

const db = getFirestore(app);

const NewUser = () => {
  const navigate = useNavigate();

  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phone: "",
    countryCode: "",
    availableDate: "",
    slot: "",
  });

  const [availableData, setAvailableData] = useState([]);
  const [errors, setErrors] = useState({});

  useEffect(() => {
    const fetchCalendarData = async () => {
      const calendarSnapshot = await getDocs(collection(db, "calendar"));
      const appointmentsSnapshot = await getDocs(collection(db, "appointments"));

      const availableDates = {};
      const bookedSlots = {};

      // Fetch available slots
      calendarSnapshot.forEach((doc) => {
        availableDates[doc.id] = doc.data().slots;
      });

      // Fetch booked slots
      appointmentsSnapshot.forEach((doc) => {
        const { availableDate, slot } = doc.data();
        if (!bookedSlots[availableDate]) {
          bookedSlots[availableDate] = [];
        }
        bookedSlots[availableDate].push(slot);
      });

      // Calculate available data
      const availableDataList = Object.entries(availableDates).map(([date, slots]) => {
        const booked = bookedSlots[date] || [];
        const availableSlots = slots.filter((slot) => !booked.includes(slot));
        return { date, slots: availableSlots };
      });

      setAvailableData(availableDataList);
    };

    fetchCalendarData();
  }, []);

  const handleSlotSelection = (date, slot) => {
    setFormData((prev) => ({ ...prev, availableDate: date, slot }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!formData.availableDate || !formData.slot) {
      setErrors({ submit: "Please select a date and time slot." });
      return;
    }

    try {
      const appointmentRef = collection(db, "appointments");

      // Add appointment details
      await setDoc(doc(appointmentRef, `${formData.availableDate}-${formData.slot}`), {
        ...formData,
      });

      alert("Appointment booked successfully!");
      navigate("/submission-success");
    } catch (error) {
      console.error("Error booking appointment:", error);
      setErrors({ submit: "Failed to book appointment. Try again later." });
    }
  };

  return (
    <div className="min-h-screen bg-red-100 flex items-center justify-center p-4">
      <div className="bg-white shadow-lg rounded-lg p-8 w-full max-w-3xl">
        <h1 className="text-2xl font-bold text-center text-red-600 mb-6">
          Book an Appointment
        </h1>

        {availableData.length > 0 ? (
          <div className="mb-6">
            {availableData.map(({ date, slots }) => (
              <div key={date} className="mb-4">
                <h2 className="text-lg font-medium text-gray-700 mb-2">{date}</h2>
                <div className="grid grid-cols-3 gap-4">
                  {slots.length > 0 ? (
                    slots.map((slot) => (
                      <button
                        key={slot}
                        onClick={() => handleSlotSelection(date, slot)}
                        className={`p-2 border rounded ${
                          formData.availableDate === date && formData.slot === slot
                            ? "bg-red-600 text-white"
                            : "bg-gray-100"
                        }`}
                      >
                        {slot}
                      </button>
                    ))
                  ) : (
                    <p className="text-gray-500">No slots available</p>
                  )}
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-gray-500 text-center">Loading available dates and slots...</p>
        )}

        <form onSubmit={handleSubmit}>
          <fieldset className="border border-red-300 rounded-lg p-6 mb-6">
            <legend className="text-lg font-semibold text-red-500 px-2">Contact Details</legend>

            <div className="mb-4">
              <label className="block text-gray-700 font-medium mb-2">Email</label>
              <input
                type="email"
                name="email"
                value={formData.email}
                onChange={(e) =>
                  setFormData((prev) => ({ ...prev, email: e.target.value }))
                }
                className="w-full border-gray-300 rounded-md shadow-sm focus:ring-red-500 focus:border-red-500"
                required
              />
            </div>

            {/* Add other fields for firstName, lastName, phone, etc. */}
          </fieldset>

          <button
            type="submit"
            className="bg-red-600 text-white font-medium py-2 px-6 rounded-lg hover:bg-red-700 transition-all"
          >
            Submit
          </button>
          {errors.submit && (
            <p className="mt-4 text-red-500 text-center font-semibold">
              {errors.submit}
            </p>
          )}
        </form>
      </div>
    </div>
  );
};

export default NewUser;

